var o=`0536-maamoul-with-dates`;var a=`world-0536`;var i=`SA`;var t=`western-asia`;var r=8;var l=61;var s={en:`Maamoul with Dates`,ua:`Маамуль із фініками`};var u={en:`A traditional dish from Saudi Arabia, centered on semolina flour, all-purpose flour, whole cow milk, date paste. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Саудівська Аравія. Основні складники: семоліна, пшеничне борошно універсальне, цільне коров'яче молоко, фінікова паста. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`semolina-flour`,350,`g`],[`unsalted-butter`,155,`g`],[`all-purpose-flour`,100,`g`],[`whole-cow-milk`,130,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:8,i:[[`date-paste`,320,`g`],[`ground-cardamom`,5,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 15 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 15 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:15,i:[]},{en:`Bake in a preheated 180°C oven for about 23 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 23 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:23,i:[]}];var g={slug:o,id:a,country:`SA`,region:t,servings:8,minutes:61,title:s,text:u,steps:d};export{i as country,g as default,a as id,l as minutes,t as region,r as servings,o as slug,d as steps,u as text,s as title};